38	 *
39	 * @example
40	 * ```typescript
41	 * // Create a custom event
42	 * const event = new SpanEvent({
43	 *   name: 'user_action',
44	 *   attributes: {
45	 *     'action.type': 'click',
46	 *     'element.id': 'submit-button'
47	 *   }
48	 * });
49	 *
50	 * // Create an event from an exception
51	 * const errorEvent = SpanEvent.fromException(new Error('Something went wrong'));
52	 * ```
53	 */
54	export class SpanEvent {
55	  /** Name of the event */
56	  readonly name: string;
