77	   * const event = new SpanEvent({
78	   *   name: 'database_query',
79	   *   attributes: {
80	   *     'db.statement': 'SELECT * FROM users',
81	   *     'db.duration_ms': 150
82	   *   }
83	   * });
84	   * ```
