// Configure json-bigint to handle large integers using native BigInt.
// This allows nanosecond timestamps to be serialized/deserialized without
// losing precision.
const JSONBig = JSONBigInt({
  useNativeBigInt: true,
  alwaysParseAsBig: false,
  storeAsString: false
});

/**
 * Safely stringify a value to JSON, handling circular references and
 * non-serializable objects (functions, undefined, Error instances).
 *
 * Uses json-bigint under the hood so that BigInt values (e.g. nanosecond
 * timestamps) are serialized correctly.
 *
 * @param value The value to stringify
 * @returns JSON string representation of the value
 */
export function safeJsonStringify(value: any): string {
  const seen = new WeakSet<object>();

  // MLflow-specific replacer that handles functions, undefined, errors, and
  // circular references.
  const mlflowReplacer = (_key: string, val: any): any => {
    if (typeof val === 'function') {
      return '[Function]';
    }
    if (val === undefined) {
      return '[Undefined]';
    }

    if (val instanceof Error) {
      return {
        name: val.name,
        message: val.message,
        stack: val.stack
      };
    }

    if (typeof val === 'object' && val !== null) {
      if (seen.has(val)) {
        return '[Circular]';
      }
      seen.add(val);
    }

    return val;
  };

  return JSONBig.stringify(value, mlflowReplacer);
}

export { JSONBig };
